// src/draw/proto/paper-cargo-r17.js
var HOLD_W = 1491;
var LANTERN = { x: 775, y: 46, w: 54, h: 72, cx: 802, cy: 77 };
var SACKS = [1071, 1168, 1274];
var SACK = { w: 76, h: 100, top: 56, tagX: 46.5 / 76, tagY: 53 / 100 };
function cargoR17(a2, prev) {
  const { d } = a2, INK2 = "#1C2A35", MID = "#687B83";
  const layer = (l2) => `<g transform="scale(${1 / TRACE_SCALE})"><path d="${l2.light}" fill="${MID}" fill-rule="evenodd" opacity=".5"/><path d="${l2.dark}" fill="${INK2}" fill-rule="evenodd"/></g>`;
  const unit = (w2) => w2 / HOLD_W, fmt = (v2) => (+v2.toFixed(2)).toString();
  const lampCenter = (w2) => ({ x: fmt(LANTERN.cx * unit(w2)), y: fmt(LANTERN.cy * unit(w2)) });
  const lit = () => d.ui.cargoLamp !== false;
  function lantern() {
    const { x: x2, y: y2, w: w2, h } = LANTERN;
    return `<g data-cargo-flame><rect x="${x2 + 15}" y="${y2 + 6}" width="${w2 - 30}" height="${h - 20}" rx="4" fill="#F3D493" opacity=".8"/><path d="M${x2 + 27} ${y2 + 48}c-3-4-3-9 0-15c3 6 3 11 0 15z" fill="#D9A04E" opacity=".9"/></g><g transform="translate(${x2} ${y2})">${layer(trace.lantern)}</g>`;
  }
  function scene(w2, h) {
    const s = unit(w2), c = lampCenter(w2);
    return `<g data-morph="deck" data-traced-scene="hold" transform="scale(${fmt(s)})"><defs><clipPath id="r17-hold-corner"><rect width="212" height="78"/></clipPath></defs><g id="r17-hold-ink">${layer(trace.hold)}</g><g clip-path="url(#r17-hold-corner)"><use href="#r17-hold-ink" transform="translate(-300 0)"/></g><g data-cargo-lantern data-center-x="${c.x}" data-center-y="${c.y}">${lantern()}</g></g>` + prev.floor(w2, h);
  }
  function light(w2, h) {
    const c = lampCenter(w2), r = Math.hypot(Math.max(+c.x, w2 - c.x), Math.max(+c.y, h - c.y));
    return `<svg class="cargo-warm-light" viewBox="0 0 ${w2} ${h}" aria-hidden="true"><defs><radialGradient id="r17-lamp-wash" gradientUnits="userSpaceOnUse" cx="${c.x}" cy="${c.y}" r="${fmt(r)}"><stop offset="0" stop-color="#F7D58C" stop-opacity=".46"/><stop offset=".08" stop-color="#F6D896" stop-opacity=".3"/><stop offset=".3" stop-color="#F3DCAB" stop-opacity=".17"/><stop offset=".62" stop-color="#F1E2C2" stop-opacity=".09"/><stop offset="1" stop-color="#F0E6D2" stop-opacity=".03"/></radialGradient></defs><rect data-cargo-glow data-center-x="${c.x}" data-center-y="${c.y}" width="${w2}" height="${h}" fill="url(#r17-lamp-wash)"/></svg>`;
  }
  function envelope() {
    return `<g transform="translate(0 0)">${layer(trace.sack)}</g>`;
  }
  function place(root) {
    const w2 = root.clientWidth, s = unit(w2);
    root.style.setProperty("--cargo-s", fmt(s));
    root.querySelectorAll(".cargo-mailbag").forEach((b3, i) => Object.assign(b3.style, { left: fmt((SACKS[i] ?? SACKS.at(-1)) * s - SACK.w * s / 2) + "px", top: fmt(SACK.top * s) + "px", width: fmt(SACK.w * s) + "px", height: fmt(SACK.h * s) + "px" }));
    const t = root.querySelector(".cargo-lamp-toggle");
    if (t) Object.assign(t.style, { left: fmt((LANTERN.x - 4) * s) + "px", top: fmt((LANTERN.y - 26) * s) + "px", width: fmt((LANTERN.w + 8) * s) + "px", height: fmt((LANTERN.h + 30) * s) + "px" });
    HOST.body.dataset.cargoLamp = lit() ? "on" : "off";
  }
  function lampButton() {
    return `<button type="button" class="cargo-lamp-toggle" data-p2="task-lamp" aria-pressed="${lit()}" aria-label="${lit() ? "\u7184\u706D\u9A6C\u706F" : "\u70B9\u4EAE\u9A6C\u706F"}"></button>`;
  }
  function toggleLamp() {
    d.ui.cargoLamp = !lit();
    HOST.body.dataset.cargoLamp = lit() ? "on" : "off";
    const t = HOST.querySelector("#tasks .cargo-lamp-toggle");
    if (t) {
      t.setAttribute("aria-pressed", String(lit()));
      t.setAttribute("aria-label", lit() ? "\u7184\u706D\u9A6C\u706F" : "\u70B9\u4EAE\u9A6C\u706F");
    }
  }
  return { scene, light, envelope, place, lampButton, toggleLamp, sackBox: SACK };
}

