function penLayer(C3, layer, { ink: ink2 = "#1C2A35", pale = "#687B83", dark = 1.15, light = 0.95 } = {}) {
  const pts = (s) => {
    const p = [];
    for (let i = 1; i < s.length; i += 2) p.push([s[i], s[i + 1]]);
    return p;
  };
  return `<g data-pen-light opacity=".7">${layer.light.map((s) => C3(pts(s), Math.max(0.4, s[0] * light), pale)).join("")}</g><g data-pen-dark>${layer.dark.map((s) => C3(pts(s), Math.max(0.55, Math.min(3, s[0] * dark)), ink2)).join("")}</g>`;
}

