    for (const x2 of [222, 252, 282, 312, 328]) s += L3([[x2, y2 - 12], [x2, y2 + 14]], 1.2);
    s += coil(300, y2 - 14, 8);
    const bx = 580;
    const sail = (x0, top, bot, w2, dir) => F2(dir < 0 ? [[x0, top], [x0 - w2, bot], [x0, bot]] : [[x0, top], [x0 + w2, bot], [x0, bot]]) + L3(dir < 0 ? [[x0, top], [x0 - w2 * 1.04, bot - 6], [x0, bot], [x0, top]] : [[x0, top], [x0 + w2 * 1.04, bot - 6], [x0, bot], [x0, top]], 1.2) + Array.from({ length: 4 }, (_2, i) => L3(dir < 0 ? [[x0 - w2 * (i + 1) / 5 * 1.02, top + (bot - top) * (i + 1) / 5], [x0, top + (bot - top) * (i + 1) / 5]] : [[x0 + w2 * (i + 1) / 5 * 1.02, top + (bot - top) * (i + 1) / 5], [x0, top + (bot - top) * (i + 1) / 5]], 0.4, M2)).join("");
